'use strict';
const products=[{id:'pies',name:'Пироги',category:'savory',tag:'К общему столу',description:'Большой повод собраться. Начинку и размер обсудим под ваш стол.',unit:'пирог',position:'40% 65%'},{id:'samsa',name:'Самса',category:'savory',tag:'Румяная история',description:'Та самая выпечка, к которой руки тянутся раньше, чем остынет чай.',unit:'штука',position:'90% 20%'},{id:'sweet',name:'Сладкая выпечка',category:'sweet',tag:'К чаю и не только',description:'Что-нибудь нежное для маленького праздника. Вид выпечки согласуем.',unit:'порция',position:'30% 75%'}];
const $=s=>document.querySelector(s);const cartDialog=$('#cartDialog');let cart={};let draft={};try{const saved=JSON.parse(localStorage.getItem('arianas-cart')||'{}');for(const p of products){const n=Number(saved[p.id]);if(Number.isInteger(n)&&n>0&&n<=99)cart[p.id]=n}draft=JSON.parse(localStorage.getItem('arianas-draft')||'{}')||{}}catch{};const persist=()=>{try{localStorage.setItem('arianas-cart',JSON.stringify(cart))}catch{}};let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function renderProducts(filter='all'){$('#products').replaceChildren();products.filter(p=>filter==='all'||p.category===filter).forEach(p=>{const el=document.createElement('article');el.className='product';el.innerHTML=`<div class="product-image"><img src="/assets/bakery.webp" alt="Иллюстрация атмосферы пекарни, не фото конкретного товара" style="object-position:${p.position}" loading="lazy"><span class="tag">${p.tag}</span></div><h3>${p.name}</h3><p>${p.description}</p><div class="product-bottom"><span>Стоимость по запросу · ${p.unit}</span><button class="add" aria-label="Добавить: ${p.name}">+</button></div>`;el.querySelector('button').addEventListener('click',()=>{if((cart[p.id]||0)>=99){toast('Максимум 99. Большой заказ укажите в пожеланиях.');return}cart[p.id]=(cart[p.id]||0)+1;updateCart();toast(`${p.name} в корзине`)});$('#products').append(el)})}
function updateCart(){persist();$('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);renderCart()}
function showEditing(){$('#orderResult').hidden=true;$('#orderForm').hidden=!Object.keys(cart).length}
function renderCart(){const container=$('#cartItems');container.replaceChildren();const selected=products.filter(p=>cart[p.id]);if(!selected.length){container.innerHTML='<div class="empty"><h3>Здесь пока только аппетит.</h3><p>Выберите что-нибудь вкусное в каталоге.</p><button class="secondary" id="browse">Перейти к выпечке</button></div>';$('#browse').onclick=()=>{cartDialog.close();location.hash='catalog'};$('#orderForm').hidden=true;$('#orderResult').hidden=true;return}for(const p of selected){const row=document.createElement('div');row.className='cart-row';row.innerHTML=`<div><strong>${p.name}</strong><p>${p.unit} · стоимость уточняется</p></div><div class="qty"><button aria-label="Убрать одну: ${p.name}">−</button><span>${cart[p.id]}</span><button aria-label="Добавить одну: ${p.name}">+</button></div>`;const buttons=row.querySelectorAll('button');buttons[0].onclick=()=>{if(--cart[p.id]<=0)delete cart[p.id];showEditing();updateCart()};buttons[1].onclick=()=>{if(cart[p.id]<99){cart[p.id]++;showEditing();updateCart()}};container.append(row)}if($('#orderResult').hidden)$('#orderForm').hidden=false}
for(const field of ['date','customer','contact','notes']){if(typeof draft[field]==='string')$('#'+field).value=draft[field];$('#'+field).addEventListener('input',()=>{draft[field]=$('#'+field).value;try{localStorage.setItem('arianas-draft',JSON.stringify(draft))}catch{}})}
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};$('#date').min=localToday();
$('#openCart').onclick=()=>{showEditing();renderCart();$('#date').min=localToday();cartDialog.showModal();document.body.classList.add('modal-open')};$('#closeCart').onclick=()=>cartDialog.close();cartDialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
$('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;document.querySelectorAll('[data-filter]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));renderProducts(b.dataset.filter)});
$('#orderForm').onsubmit=e=>{e.preventDefault();if(!Object.keys(cart).length)return;if($('#date').value<localToday()){toast('Выберите сегодняшнюю или будущую дату');return}if(!$('#customer').value.trim()||!$('#contact').value.trim()){toast('Заполните имя и контакт для связи');return}const date=$('#date').value.split('-').reverse().join('.');const text=['Здравствуйте, Ариана! Хочу обсудить заказ:','',...products.filter(p=>cart[p.id]).map(p=>`${p.name}: ${cart[p.id]} (${p.unit})`),'',`Желаемая дата: ${date}`,`Имя: ${$('#customer').value.trim()}`,`Связь: ${$('#contact').value.trim()}`,`Пожелания: ${$('#notes').value.trim()||'обсудим лично'}`,'','Подскажите, пожалуйста, доступность, состав, стоимость и условия получения.'].join('\n');$('#orderText').value=text;$('#orderResult').hidden=false;$('#orderForm').hidden=true};
$('#copyOrder').onclick=async()=>{try{await navigator.clipboard.writeText($('#orderText').value);toast('Текст скопирован. Можно отправить лично.')}catch{$('#orderText').focus();$('#orderText').select();toast('Выделили текст. Нажмите «Копировать».')}};$('#shareOrder').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'Заявка Ariana’s',text:$('#orderText').value})}catch(e){if(e.name!=='AbortError')toast('Не удалось поделиться. Скопируйте текст.')}}else $('#copyOrder').click()};$('#editOrder').onclick=showEditing;
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else{$('#installDialog').showModal();document.body.classList.add('modal-open')}};$('#closeInstall').onclick=()=>$('#installDialog').close();$('#installDialog').addEventListener('close',()=>document.body.classList.remove('modal-open'));for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
renderProducts();updateCart();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
